// T055: Environment validation using trigger_release_deployment tool
const input = $json.body;

// Validate required fields
if (!input.release_version || !input.release_type || !input.ticket_ids) {
  return {
    valid: false,
    error: 'Missing required fields: release_version, release_type, ticket_ids'
  };
}

// Call MCP tool for validation
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const response = await $http.post(`${mcpServerUrl}/tool/trigger_release_deployment`, {
  jsonrpc: '2.0',
  id: $executionId,
  method: 'trigger_release_deployment',
  params: {
    release_version: input.release_version,
    release_type: input.release_type,
    target_environment: input.target_environment,
    ticket_ids: input.ticket_ids,
    tenant_ids: input.tenant_ids,
    created_by: input.created_by || 'n8n-workflow'
  }
});

const result = response.data.result;

if (!result.validation.valid) {
  return {
    valid: false,
    errors: result.validation.errors,
    release_id: ''
  };
}

return {
  valid: true,
  release_id: result.release_id,
  release_version: result.release_version,
  target_environment: result.target_environment,
  ticket_ids: result.ticket_ids,
  tenant_ids: result.tenant_ids
};

// Call jira_get_release_tickets MCP tool
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const response = await $http.post(`${mcpServerUrl}/tool/jira_get_release_tickets`, {
  jsonrpc: '2.0',
  id: $executionId,
  method: 'jira_get_release_tickets',
  params: {
    release_version: $json.release_version
  }
});

const result = response.data.result;
return {
  release_id: $json.release_id,
  tickets: result.tickets,
  ticket_count: result.total_count
};

// Loop through tickets and check approvals
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const tickets = $json.tickets;
const approvalResults = [];

for (const ticket of tickets) {
  const response = await $http.post(`${mcpServerUrl}/tool/git_check_pr_approvals`, {
    jsonrpc: '2.0',
    id: $executionId,
    method: 'git_check_pr_approvals',
    params: {
      pr_id: ticket.pr_id,
      required_approvals: 2
    }
  });

  const result = response.data.result;
  approvalResults.push({
    ticket_id: ticket.id,
    pr_id: ticket.pr_id,
    approved: result.approved,
    approval_count: result.approval_count,
    pr_owner_email: result.pr_owner_email,
    potential_reviewers: result.potential_reviewers
  });
}

const allApproved = approvalResults.every(r => r.approved);
const insufficientApprovals = approvalResults.filter(r => !r.approved);

return {
  release_id: $json.release_id,
  tickets: $json.tickets,
  approval_results: approvalResults,
  all_approved: allApproved,
  insufficient_approvals: insufficientApprovals
};

// Notify PR owners about insufficient approvals
// In production, this would call teams_notify_pr_owner tool
const insufficientApprovals = $json.insufficient_approvals;

return {
  message: 'Workflow paused: Waiting for PR approvals',
  insufficient_approvals: insufficientApprovals,
  action_required: 'Manual intervention needed'
};

// Call git_merge_tickets_to_development MCP tool
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const tickets = $json.tickets;

const mergeTickets = tickets.map(t => ({
  ticket_id: t.id,
  pr_id: t.pr_id,
  squash_commit_message: `[${t.id}] ${t.summary}`
}));

const response = await $http.post(`${mcpServerUrl}/tool/git_merge_tickets_to_development`, {
  jsonrpc: '2.0',
  id: $executionId,
  method: 'git_merge_tickets_to_development',
  params: {
    tickets: mergeTickets,
    target_branch: 'development',
    auto_resolve_conflicts: false
  }
});

const result = response.data.result;

return {
  release_id: $json.release_id,
  merged: result.merged,
  conflicts: result.conflicts,
  failed: result.failed,
  has_conflicts: result.conflicts.length > 0
};

// Call git_create_release_branch MCP tool
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const input = $input.first().json;

const response = await $http.post(`${mcpServerUrl}/tool/git_create_release_branch`, {
  jsonrpc: '2.0',
  id: $executionId,
  method: 'git_create_release_branch',
  params: {
    release_version: input.release_version,
    release_type: input.release_type,
    source_branch: 'development'
  }
});

const result = response.data.result;

return {
  release_id: input.release_id,
  branch_name: result.branch_name,
  commit_sha: result.commit_sha,
  tenant_ids: input.tenant_ids,
  target_environment: input.target_environment
};

// Call jenkins_trigger_deployment MCP tool
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';

const response = await $http.post(`${mcpServerUrl}/tool/jenkins_trigger_deployment`, {
  jsonrpc: '2.0',
  id: $executionId,
  method: 'jenkins_trigger_deployment',
  params: {
    tenant_ids: $json.tenant_ids,
    release_branch: $json.branch_name,
    target_environment: $json.target_environment,
    tenant_configurations: [] // Would be loaded from environment config
  }
});

const result = response.data.result;

return {
  release_id: $json.release_id,
  triggered: result.triggered,
  failed: result.failed,
  target_environment: $json.target_environment
};

// Poll jenkins_get_job_status until all complete
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const maxPolls = 60; // 30 minutes (30s intervals)
let polls = 0;
let allComplete = false;
let statuses = [];

while (!allComplete && polls < maxPolls) {
  const response = await $http.post(`${mcpServerUrl}/tool/jenkins_get_job_status`, {
    jsonrpc: '2.0',
    id: $executionId,
    method: 'jenkins_get_job_status',
    params: {
      jobs: $json.triggered
    }
  });

  const result = response.data.result;
  statuses = result.statuses;

  allComplete = statuses.every(s => 
    s.status === 'success' || s.status === 'failed' || s.status === 'cancelled'
  );

  if (!allComplete) {
    await new Promise(resolve => setTimeout(resolve, 30000)); // 30s
    polls++;
  }
}

const successful = statuses.filter(s => s.status === 'success');
const failed = statuses.filter(s => s.status === 'failed');

return {
  release_id: $json.release_id,
  statuses: statuses,
  successful_tenants: successful.map(s => s.tenant_id),
  failed_tenants: failed.map(s => s.tenant_id),
  all_successful: failed.length === 0
};

// Call jira_update_ticket_status MCP tool
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const input = $input.first().json;
const ticketIds = input.ticket_ids || [];

const newStatus = input.all_successful ? 'Deployed' : 'Partially Deployed';
const comment = input.all_successful
  ? `Deployed successfully to ${input.target_environment}`
  : `Partial deployment: ${input.successful_tenants.length}/${input.successful_tenants.length + input.failed_tenants.length} tenants`;

const response = await $http.post(`${mcpServerUrl}/tool/jira_update_ticket_status`, {
  jsonrpc: '2.0',
  id: $executionId,
  method: 'jira_update_ticket_status',
  params: {
    ticket_ids: ticketIds,
    new_status: newStatus,
    comment: comment
  }
});

const result = response.data.result;

return {
  release_id: input.release_id,
  updated: result.updated,
  failed: result.failed,
  deployment_summary: input
};

// Call teams_announce_deployment MCP tool
const mcpServerUrl = $env.MCP_SERVER_URL || 'http://localhost:3000';
const summary = $json.deployment_summary;

const response = await $http.post(`${mcpServerUrl}/tool/teams_announce_deployment`, {
  jsonrpc: '2.0',
  id: $executionId,
  method: 'teams_announce_deployment',
  params: {
    release_version: summary.release_version,
    target_environment: summary.target_environment,
    summary: {
      ticket_count: summary.ticket_ids.length,
      duration_minutes: 15, // Calculate from workflow start
      successful_tenants: summary.successful_tenants,
      failed_tenants: summary.failed_tenants,
      cache_cleared_count: summary.successful_tenants.length,
      total_tenants: summary.successful_tenants.length + summary.failed_tenants.length
    }
  }
});

const result = response.data.result;

return {
  release_id: $json.release_id,
  announcement_sent: result.delivered,
  message_id: result.message_id,
  workflow_complete: true
};
